head.script:
scwin.onpageload = function() {
    console.log("onpageload " + $p.getParameter("w2xPath") + " Frame");
};
scwin.onpageunload = function() {};
scwin.ibx_openPopup_onclick = function(e) {
    requires("uiplugin.popup");
    var options = {
        id: "popup1",
        type: "window",
        width: "700px",
        height: "600px",
        top: "130px",
        left: "400px",
        popupName: "openPopup1",
        modal: true,
        useIFrame: true,
        scrollbars: "true",
        resizable: "true",
        menubar: true,
        frameMode: "wframe",
        useModalStack: true,
        alwaysOnTop: false,
        useControl: true
    };
    $p.openPopup("popup_openPopup_WPFF-208_(WSQ-3494)_wframe1.xml", options);
};
scwin.checkLog1 = function() {
    return (localStorage.getItem("window.log1") == window.a);
}
scwin.checkLog2 = function() {
    return (localStorage.getItem("window.log2") == '$p.parent().$p.getFrameId() : '+$p.id+'popup1_wframe');
}
scwin.checkLog3 = function() {
    return (localStorage.getItem("window.log3") == '$p.parent().scwin.popupId : '+$p.id+'popup1');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('ibx_openPopup').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "localStorage.removeItem('window.log')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.a = '$p.getRuntimeId("scwin", "parent") : '+$p.id+'popup1_wframe_scwin';
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
